    private int attendedMinutes;

    public TimePlan(String planName, int targetMinutes) {
        super(planName);
        this.targetMinutes = targetMinutes;
        this.attendedMinutes = 0;
    }

    @Override
    public void attend(int minutes) {
    }

    @Override
    public String getProgress() {
        return "";
    }
}

class SessionPlan extends TrainingPlan {
    private int requiredSessions;
    private int completedSessions;

    public SessionPlan(String planName, int requiredSessions) {
        super(planName);
        this.requiredSessions = requiredSessions;
        this.completedSessions = 0;
    }

    @Override
    public void attend(int minutes) {
    }

    @Override
    public String getProgress() {
        return "";
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String type = sc.next();
        String planName = sc.next();

        TrainingPlan plan;
        if (type.equals("TIME")) {
            int targetMinutes = sc.nextInt();
            plan = new TimePlan(planName, targetMinutes);
        } else {
            int requiredSessions = sc.nextInt();
            plan = new SessionPlan(planName, requiredSessions);
        }

        int firstAttend = sc.nextInt();
        int secondAttend = sc.nextInt();

        plan.attend(firstAttend);
        plan.attend(secondAttend);

        System.out.println(plan.getPlanName() + ":" + plan.getProgress());
    }
}

